function ExImg({ ex, size = 40 }) {
  const src = ex && IMGS[ex.id];
  const st = { width: size, height: size };
  if (src) return <img src={src} alt="" style={st} className="shrink-0 rounded-full object-cover" />;
  return (
    <div style={st} className="flex shrink-0 items-center justify-center rounded-full bg-neutral-800 text-xs font-semibold text-neutral-400">
      {(ex?.name || "?").slice(0, 2).toUpperCase()}
    </div>
  );
}

// ---------- sound ----------
let actx = null;
function unlockAudio() {
  try {
    if (!actx) { const C = window.AudioContext || window.webkitAudioContext; actx = new C(); }
    if (actx.state === "suspended") actx.resume();
  } catch (e) {}
}
function beep() {
  if (!actx) return;
  try {
    [0, 0.35, 0.7].forEach((t) => {
      const o = actx.createOscillator(), g = actx.createGain();
      o.frequency.value = 880;
      o.connect(g); g.connect(actx.destination);
      const s = actx.currentTime + t;
      g.gain.setValueAtTime(0.0001, s);
      g.gain.exponentialRampToValueAtTime(0.35, s + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, s + 0.25);
      o.start(s); o.stop(s + 0.3);
    });
  } catch (e) {}
}

// ---------- small UI ----------
function ConfirmButton({ onConfirm, children, className = "", armedClassName = "", confirmText = "Точно?" }) {
  const [armed, setArmed] = useState(false);
  useEffect(() => {
    if (!armed) return;
    const t = setTimeout(() => setArmed(false), 3000);
    return () => clearTimeout(t);
  }, [armed]);
  return (
    <button
      className={armed ? armedClassName : className}
      onClick={() => (armed ? (setArmed(false), onConfirm()) : setArmed(true))}
    >
      {armed ? confirmText : children}
    </button>
  );
}

function Header({ title, back, right }) {
  return (
    <div className="flex items-center gap-2 mb-4">
      {back && (
        <button onClick={back} className="-ml-2 p-2 text-neutral-400" aria-label="Назад">
          <ChevronLeft size={24} />
        </button>
      )}
      <h1 className="flex-1 text-xl font-bold tracking-tight">{title}</h1>
      {right}
    </div>
  );
}

function Stepper({ value, onChange, step = 1, min = 1, fmt = (v) => v, compact }) {
  const btn = compact ? "p-1.5 text-neutral-300" : "p-2 text-neutral-300";
  return (
    <div className="flex items-center rounded-lg bg-neutral-800">
      <button className={btn} onClick={() => onChange(Math.max(min, value - step))}><Minus size={compact ? 14 : 16} /></button>
      <span className={`${compact ? "w-6" : "w-12"} text-center tabular-nums`}>{fmt(value)}</span>
      <button className={btn} onClick={() => onChange(value + step)}><Plus size={compact ? 14 : 16} /></button>
    </div>
  );
}

// ---------- exercise list (used in tab and picker) ----------
function ExerciseList({ data, up, onSelect, autoFocus }) {
  const [q, setQ] = useState("");
  const [grp, setGrp] = useState("спина");
  const [kind, setKind] = useState("reps");
  const ql = q.trim().toLowerCase();
  const allGroups = [...GROUPS, ...new Set(data.exercises.map((e) => e.group).filter((g) => !GROUPS.includes(g)))];
  const filtered = data.exercises.filter((e) => !ql || e.name.toLowerCase().includes(ql) || (e.ru || "").toLowerCase().includes(ql) || e.group.includes(ql));
  const byGroup = allGroups
    .map((g) => [g, filtered.filter((e) => e.group === g).sort((a, b) => a.name.localeCompare(b.name))])
    .filter(([, l]) => l.length);
  const exact = data.exercises.some((e) => e.name.toLowerCase() === ql || (e.ru || "").toLowerCase() === ql);

  const create = () => {
    const ex = { id: uid(), name: q.trim(), group: grp, kind };
    up((d) => { d.exercises.push(ex); });
    setQ("");
    onSelect(ex);
  };

  return (
    <div>
      <div className="flex items-center gap-2 rounded-xl bg-neutral-900 px-3">
        <Search size={18} className="text-neutral-500" />
        <input
          autoFocus={autoFocus}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Поиск или новое упражнение"
          className="flex-1 bg-transparent py-3 outline-none placeholder-neutral-500"
        />
        {q && <button onClick={() => setQ("")} className="text-neutral-500"><X size={18} /></button>}
      </div>

      {ql && !exact && (
        <div className="mt-3 rounded-xl border border-dashed border-neutral-700 p-3">
          <div className="text-xs text-neutral-300 mb-2">Создать «{q.trim()}»</div>
          <div className="flex flex-wrap gap-1.5 mb-3">
            {GROUPS.map((g) => (
              <button key={g} onClick={() => setGrp(g)}
                className={`rounded-full px-3 py-1 text-xs ${grp === g ? "bg-amber-400 text-neutral-900" : "bg-neutral-800 text-neutral-300"}`}>
                {g}
              </button>
            ))}
          </div>
          <div className="flex gap-1.5 mb-3">
            {[["reps", "вес и повторы"], ["time", "вес и время"]].map(([k, l]) => (
              <button key={k} onClick={() => setKind(k)}
                className={`rounded-full px-3 py-1 text-xs ${kind === k ? "bg-neutral-100 text-neutral-900" : "bg-neutral-800 text-neutral-300"}`}>
                {l}
              </button>
            ))}
          </div>
          <button onClick={create} className="w-full rounded-lg bg-amber-400 py-2.5 font-semibold text-neutral-900">
            Создать
          </button>
        </div>
      )}

      {byGroup.map(([g, list]) => (
        <div key={g} className="mt-4">
          <div className="text-xs text-neutral-500 mb-1 px-1">{g}</div>
          <div className="rounded-xl bg-neutral-900 divide-y divide-neutral-800">
            {list.map((e) => (
              <button key={e.id} onClick={() => onSelect(e)} className="flex w-full items-center gap-3 text-left px-3 py-2 active:bg-neutral-800">
                <ExImg ex={e} />
                <span className="min-w-0 flex-1">
                  <span className="block">{e.name}</span>
                  {e.ru && <span className="block text-xs text-neutral-500">{e.ru}</span>}
                </span>
                {e.kind === "time" && <span className="ml-2 text-xs text-neutral-500">на время</span>}
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function Picker({ data, up, onPick, onClose, title = "Добавить упражнение" }) {
  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black" style={{ paddingTop: "env(safe-area-inset-top)" }}>
      <div className="mx-auto max-w-md p-4 pb-24">
        <Header title={title} right={<button onClick={onClose} className="p-2 text-neutral-400"><X size={22} /></button>} />
        <ExerciseList data={data} up={up} onSelect={onPick} autoFocus />
      </div>
    </div>
  );
}


// ---------- drag to reorder (hold the grip and pull) ----------
function moveItem(xs, from, to) { const [x] = xs.splice(from, 1); xs.splice(to, 0, x); }

function useSortable(onMove) {
  const [drag, setDrag] = useState(null); // {from, to, dy}
  const refs = useRef([]);
  const st = useRef(null);
  const raf = useRef(0);
  const onMoveRef = useRef(onMove);
  onMoveRef.current = onMove;

  const update = () => {
    const s = st.current;
    if (!s || !s.rects) return;
    const finger = s.y + window.scrollY;
    const r = s.rects[s.from];
    const dy = finger - (r.top + r.h / 2);
    let to = s.from;
    s.rects.forEach((q, j) => {
      const mid = q.top + q.h / 2;
      if (j > s.from && finger > mid) to = Math.max(to, j);
      if (j < s.from && finger < mid) to = Math.min(to, j);
    });
    if (dy !== s.dy || to !== s.to) { s.dy = dy; s.to = to; setDrag({ from: s.from, to, dy }); }
  };

  // measure after the list has re-rendered in compact drag mode
  useLayoutEffect(() => {
    const s = st.current;
    if (!drag || !s || s.rects) return;
    s.rects = refs.current.slice(0, s.count).map((el) => {
      const r = el.getBoundingClientRect();
      return { top: r.top + window.scrollY, h: r.height };
    });
    s.gap = s.rects.length > 1 ? s.rects[1].top - (s.rects[0].top + s.rects[0].h) : 8;
    update();
    const loop = () => {
      const c = st.current;
      if (!c) return;
      if (c.y < 90) window.scrollBy(0, -10);
      else if (c.y > window.innerHeight - 150) window.scrollBy(0, 10);
      update();
      raf.current = requestAnimationFrame(loop);
    };
    raf.current = requestAnimationFrame(loop);
  }, [drag]);

  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  const end = () => {
    cancelAnimationFrame(raf.current);
    const s = st.current;
    st.current = null;
    setDrag(null);
    if (s && s.to !== s.from) onMoveRef.current(s.from, s.to);
  };

  const handleProps = (i, count) => ({
    style: { touchAction: "none" },
    onPointerDown: (ev) => {
      ev.preventDefault();
      try { ev.currentTarget.setPointerCapture(ev.pointerId); } catch (e) {}
      st.current = { from: i, to: i, y: ev.clientY, count, rects: null, dy: 0 };
      setDrag({ from: i, to: i, dy: 0 });
      try { navigator.vibrate && navigator.vibrate(15); } catch (e) {}
    },
    onPointerMove: (ev) => { if (st.current) { st.current.y = ev.clientY; update(); } },
    onPointerUp: end,
    onPointerCancel: end,
  });

  const itemStyle = (i) => {
    const s = st.current;
    if (!drag || !s || !s.rects) return undefined;
    const h = s.rects[drag.from].h + s.gap;
    if (i === drag.from)
      return { transform: `translateY(${drag.dy}px)`, position: "relative", zIndex: 30, boxShadow: "0 12px 32px rgba(0,0,0,0.8)" };
    if (drag.from < drag.to && i > drag.from && i <= drag.to) return { transform: `translateY(${-h}px)`, transition: "transform 150ms" };
    if (drag.from > drag.to && i < drag.from && i >= drag.to) return { transform: `translateY(${h}px)`, transition: "transform 150ms" };
    return { transition: "transform 150ms" };
  };

  return { refs, handleProps, itemStyle, dragging: !!drag, dragFrom: drag ? drag.from : -1 };
}

// ---------- workout ----------
function startWorkout(up, p) {
  up((d) => {
    d.active = {
      id: uid(),
      programId: p?.id || null,
      name: p?.name || "Свободная тренировка",
      startedAt: Date.now(),
      segments: [{ start: Date.now() }],
      paused: false,
      restEndsAt: null,
      exercises: (p?.items || []).map((it) => ({ exerciseId: it.exerciseId, sets: buildSets(d, it.exerciseId, it.sets) })),
    };
  });
}

function WorkoutTab({ data, up, exMap, open }) {
  const a = data.active;
  const [picker, setPicker] = useState(false);
  const [askUpdate, setAskUpdate] = useState(false);
  const now = useNow(1000, !!a && !a.paused);
  const sort = useSortable((from, to) => up((d) => { moveItem(d.active.exercises, from, to); }));

  if (!a) {
    const last = data.workouts[data.workouts.length - 1];
    return (
      <div className="p-4">
        <Header title="Тренировка" />
        {last && <p className="text-xs text-neutral-400 mb-3">Прошлая: {last.name}, {fmtDate(last.startedAt)}</p>}
        {data.pendingProgramUpdate && data.programs.some((x) => x.id === data.pendingProgramUpdate.programId) && (
          <div className="mb-3 rounded-xl bg-neutral-900 p-4">
            <div className="font-semibold">Вчерашняя тренировка завершена</div>
            <p className="mb-3 text-xs text-neutral-400">
              Она отличалась от «{data.programs.find((x) => x.id === data.pendingProgramUpdate.programId).name}». Записать изменения в программу?
            </p>
            <div className="flex gap-2">
              <button onClick={() => up((d) => { delete d.pendingProgramUpdate; })} className="rounded-xl bg-neutral-800 px-4 py-2.5 text-neutral-300">Нет</button>
              <button onClick={() => up((d) => {
                const pu = d.pendingProgramUpdate;
                const pp = pu && d.programs.find((x) => x.id === pu.programId);
                if (pp) pp.items = pu.items;
                delete d.pendingProgramUpdate;
              })} className="flex-1 rounded-xl bg-amber-400 py-2.5 font-semibold text-black">Обновить программу</button>
            </div>
          </div>
        )}
        <div className="space-y-2">
          {data.programs.map((p) => (
            <div key={p.id} className="flex items-stretch gap-2 rounded-xl bg-neutral-900 p-2 pl-4">
              <button onClick={() => open({ type: "program", id: p.id })} className="min-w-0 flex-1 py-2 text-left">
                <div className="text-base font-semibold">{p.name}</div>
                <div className="mt-1 text-xs text-neutral-400">
                  {p.items.map((i) => exMap[i.exerciseId]?.name).filter(Boolean).join(", ") || "Пока без упражнений"}
                </div>
              </button>
              <button onClick={() => startWorkout(up, p)} aria-label="Начать"
                className="flex w-14 shrink-0 items-center justify-center rounded-lg bg-amber-400 text-black">
                <Play size={22} />
              </button>
            </div>
          ))}
          <button onClick={() => startWorkout(up, null)} className="w-full rounded-xl border border-dashed border-neutral-700 p-4 text-neutral-300">
            Начать без программы
          </button>
        </div>
      </div>
    );
  }

  const st = stats(a, exMap);
  const setSet = (ei, si, patch) => up((d) => { Object.assign(d.active.exercises[ei].sets[si], patch); });
  const toggle = (ei, si) => {
    unlockAudio();
    up((d) => {
      const s = d.active.exercises[ei].sets[si];
      s.done = !s.done;
      if (s.done && d.active.paused) { closeSegment(d.active); d.active.segments.push({ start: Date.now() }); d.active.paused = false; }
      if (s.done) d.active.restEndsAt = Date.now() + d.settings.restSec * 1000;
    });
  };
  const addSet = (ei) => up((d) => {
    const ss = d.active.exercises[ei].sets, l = ss[ss.length - 1];
    ss.push({ w: l ? l.w : "", r: l ? l.r : "", p: l && l.p ? l.p : "", done: false });
  });
  const delSet = (ei, si) => up((d) => { d.active.exercises[ei].sets.splice(si, 1); });
  const delEx = (ei) => up((d) => { d.active.exercises.splice(ei, 1); });
  const moveEx = (ei, dir) => up((d) => {
    const xs = d.active.exercises, j = ei + dir;
    if (j < 0 || j >= xs.length) return;
    [xs[ei], xs[j]] = [xs[j], xs[ei]];
  });
  const addEx = (ex) => {
    const rep = picker.replace;
    up((d) => {
      if (rep !== undefined) {
        const e = d.active.exercises[rep];
        if (e) { e.exerciseId = ex.id; e.sets = buildSets(d, ex.id, e.sets.length || 3); }
      } else d.active.exercises.push({ exerciseId: ex.id, sets: buildSets(d, ex.id, 3) });
    });
    setPicker(false);
  };
  const hasDone = a.exercises.some((e) => e.sets.some((s) => s.done));
  const program = a.programId ? data.programs.find((p) => p.id === a.programId) : null;
  const newItems = a.exercises.map((e) => ({ exerciseId: e.exerciseId, sets: e.sets.length || 1 }));
  const programChanged = !!program && JSON.stringify(program.items) !== JSON.stringify(newItems);
  const finish = () => (programChanged ? setAskUpdate(true) : doFinish(false));
  const doFinish = (updateProgram) => {
    setAskUpdate(false);
    const id = a.id;
    up((d) => { finalizeActive(d, updateProgram); });
    if (hasDone) open({ type: "workout", id });
  };
  const pause = () => up((d) => { closeSegment(d.active); d.active.paused = true; d.active.restEndsAt = null; });
  const resume = () => up((d) => { closeSegment(d.active); d.active.segments.push({ start: Date.now() }); d.active.paused = false; });
  const segs = segmentsOf(a);
  const cur = segs[segs.length - 1];
  const dur = durations(a, now);

  return (
    <div className="p-4 pb-44">
      <div className="mb-4 flex items-start justify-between gap-3">
        <div>
          <p className="text-xs text-neutral-400">{a.paused ? "На паузе" : segs.length > 1 ? `Продолжение, отрезок ${segs.length}` : "Идёт тренировка"}</p>
          <h1 className="text-lg font-bold">{a.name}</h1>
        </div>
        <div className="text-right">
          <div className={`text-2xl font-bold tabular-nums ${a.paused ? "text-neutral-500" : "text-amber-400"}`}>
            {a.paused ? fmtDur(dur.main) : fmtDur(now - cur.start)}
          </div>
          <div className="text-xs text-neutral-400 tabular-nums">
            {st.sets} подх., {fmtKg(st.vol)}
            {segs.length > 1 && <span className="block">основная {fmtDur(dur.main)}{dur.extra >= 60000 ? `, +${fmtDur(dur.extra)}` : ""}</span>}
          </div>
        </div>
      </div>

      {a.paused && (
        <button onClick={resume} className="mb-3 flex w-full items-center justify-center gap-2 rounded-xl bg-amber-400 py-3 font-semibold text-black">
          <Play size={18} /> Продолжить тренировку
        </button>
      )}

      {a.exercises.map((e, ei) => {
        const ex = exMap[e.exerciseId] || { name: "Удалённое упражнение", kind: "reps" };
        const last = lastSession(data.workouts, e.exerciseId);
        return (
          <div key={ei + e.exerciseId} ref={(el) => { sort.refs.current[ei] = el; }} style={sort.itemStyle(ei)}
            className={`mb-3 rounded-xl p-3 ${sort.dragFrom === ei ? "bg-neutral-800" : "bg-neutral-900"}`}>
            <div className={`flex items-center gap-1 ${sort.dragging ? "" : "mb-2"}`}>
              <button {...sort.handleProps(ei, a.exercises.length)} className="-ml-1 cursor-grab p-1 text-neutral-500" aria-label="Перетащить">
                <GripVertical size={20} />
              </button>
              <ExImg ex={exMap[e.exerciseId]} />
              <button onClick={() => open({ type: "exercise", id: e.exerciseId })} className="ml-2 min-w-0 flex-1 text-left">
                <div className="font-semibold">{ex.name}</div>
                {ex.ru && <div className="truncate text-xs text-neutral-500">{ex.ru}</div>}
                {last && !sort.dragging && <div className="truncate text-xs text-neutral-400">Прошлый раз: {fmtSets(last.sets, ex.kind)}</div>}
              </button>
              <button onClick={() => setPicker({ replace: ei })} className="p-1.5 text-neutral-500" aria-label="Заменить"><RefreshCw size={18} /></button>
              <ConfirmButton onConfirm={() => delEx(ei)} className="p-1.5 text-neutral-500" armedClassName="rounded-md bg-red-600 px-2 py-1 text-xs text-white">
                <Trash2 size={18} />
              </ConfirmButton>
            </div>
            {!sort.dragging && (<>
            <div className="flex items-center gap-2 px-1 text-xs text-neutral-500">
              <span className="w-5" /><span className="flex-1 text-center">кг</span>
              <span className="flex-1 text-center">{ex.kind === "time" ? "сек" : "повт."}</span>
              <span className="w-11 text-center">{ex.kind === "time" ? "" : "частич."}</span>
              <span className="w-11" /><span className="w-6" />
            </div>
            {e.sets.map((s, si) => (
              <div key={si} className="mt-1.5 flex items-center gap-2 px-1">
                <span className={`w-5 text-xs ${s.done ? "text-amber-400" : "text-neutral-500"}`}>{si + 1}</span>
                <input value={s.w} inputMode="decimal" onChange={(ev) => setSet(ei, si, { w: ev.target.value })}
                  className={`min-w-0 flex-1 rounded-lg bg-black px-2 py-2.5 text-center text-base tabular-nums outline-none focus:ring-2 focus:ring-amber-400 ${s.done ? "text-amber-300" : ""}`} />
                <input value={s.r} inputMode="numeric" onChange={(ev) => setSet(ei, si, { r: ev.target.value })}
                  className={`min-w-0 flex-1 rounded-lg bg-black px-2 py-2.5 text-center text-base tabular-nums outline-none focus:ring-2 focus:ring-amber-400 ${s.done ? "text-amber-300" : ""}`} />
                {ex.kind === "time" ? <span className="w-11" /> : (
                  <input value={s.p || ""} inputMode="numeric" placeholder="+" aria-label="Частичные повторы"
                    onChange={(ev) => setSet(ei, si, { p: ev.target.value })}
                    className={`w-11 rounded-lg bg-black px-1 py-2.5 text-center text-base tabular-nums outline-none placeholder-neutral-600 focus:ring-2 focus:ring-amber-400 ${s.done ? "text-amber-300" : "text-neutral-300"}`} />
                )}
                <button onClick={() => toggle(ei, si)} aria-label="Подход сделан"
                  className={`flex h-11 w-11 items-center justify-center rounded-lg ${s.done ? "bg-amber-400 text-neutral-900" : "bg-neutral-800 text-neutral-400"}`}>
                  <Check size={22} />
                </button>
                <button onClick={() => delSet(ei, si)} className="w-6 text-neutral-600" aria-label="Удалить подход"><X size={16} /></button>
              </div>
            ))}
            <button onClick={() => addSet(ei)} className="mt-2 w-full rounded-lg py-2 text-xs text-neutral-400 active:bg-neutral-800">
              Добавить подход
            </button>
            </>)}
          </div>
        );
      })}

      <button onClick={() => setPicker(true)} className="w-full rounded-xl border border-dashed border-neutral-700 py-3 text-neutral-300">
        Добавить упражнение
      </button>

      <div className="mt-6 flex gap-2">
        <ConfirmButton onConfirm={() => up((d) => { d.active = null; })} confirmText="Удалить тренировку?"
          className="rounded-xl bg-neutral-900 px-4 py-3 text-neutral-400" armedClassName="rounded-xl bg-red-600 px-4 py-3 text-white">
          Отменить
        </ConfirmButton>
        {a.paused ? (
          <>
            <button onClick={resume} className="flex-1 rounded-xl bg-amber-400 py-3 font-semibold text-black">Продолжить</button>
            <button onClick={finish} className="rounded-xl bg-neutral-800 px-4 py-3">Завершить</button>
          </>
        ) : (
          <>
            <button onClick={pause} className="rounded-xl bg-neutral-800 px-4 py-3">Пауза</button>
            <button onClick={finish} className="flex-1 rounded-xl bg-amber-400 py-3 font-semibold text-black">Завершить</button>
          </>
        )}
      </div>

      {askUpdate && (
        <div className="fixed inset-0 z-50 flex items-end bg-black/70 p-3" onClick={() => setAskUpdate(false)}>
          <div className="safe-bottom mx-auto w-full max-w-md rounded-2xl bg-neutral-900 p-4" onClick={(e) => e.stopPropagation()}>
            <div className="mb-1 text-base font-semibold">Обновить программу?</div>
            <p className="mb-4 text-xs text-neutral-400">
              Состав или подходы отличаются от «{program?.name}». Можно записать в программу то, как ты тренировался сегодня.
            </p>
            <button onClick={() => doFinish(true)} className="mb-2 w-full rounded-xl bg-amber-400 py-3 font-semibold text-black">Обновить программу</button>
            <button onClick={() => doFinish(false)} className="w-full rounded-xl bg-neutral-800 py-3 text-neutral-300">Оставить программу как была</button>
          </div>
        </div>
      )}

      {picker && <Picker data={data} up={up} onPick={addEx} onClose={() => setPicker(false)}
        title={picker.replace !== undefined ? "Заменить упражнение" : undefined} />}
    </div>
  );
}

function RestBar({ endsAt, total, up }) {
  const now = useNow(250, true);
  const left = endsAt - now;
  const done = left <= 0;
  const fired = useRef(null);
  useEffect(() => {
    if (!done) return;
    if (fired.current !== endsAt) {
      fired.current = endsAt;
      if (Date.now() - endsAt < 5000) {
        beep();
        try { navigator.vibrate && navigator.vibrate([300, 150, 300]); } catch (e) {}
      }
    }
    const t = setTimeout(() => up((d) => { if (d.active) d.active.restEndsAt = null; }), 2500);
    return () => clearTimeout(t);
  }, [done, endsAt]);
  const adjust = (sec) => up((d) => { if (d.active?.restEndsAt) d.active.restEndsAt += sec * 1000; });
  const pct = Math.min(100, Math.max(0, (left / (total * 1000)) * 100));

  return (
    <div className="above-nav fixed inset-x-0 z-40 px-3">
      <div className={`mx-auto max-w-md overflow-hidden rounded-2xl shadow-lg ${done ? "bg-amber-400 text-neutral-900" : "bg-neutral-100 text-neutral-900"}`}>
        <div className="h-1.5 bg-neutral-300"><div className="h-full bg-amber-500" style={{ width: `${pct}%`, transition: "width 250ms linear" }} /></div>
        <div className="flex items-center gap-2 p-3">
          <div className="flex-1">
            <div className="text-xs text-neutral-600">{done ? "Время подхода" : "Отдых"}</div>
            <div className="text-2xl font-bold tabular-nums">{done ? "0:00" : fmtDur(left + 999)}</div>
          </div>
          <button onClick={() => adjust(-15)} className="rounded-lg bg-neutral-300 px-3 py-2 font-semibold tabular-nums">−15</button>
          <button onClick={() => adjust(15)} className="rounded-lg bg-neutral-300 px-3 py-2 font-semibold tabular-nums">+15</button>
          <button onClick={() => up((d) => { if (d.active) d.active.restEndsAt = null; })} className="rounded-lg bg-black px-3 py-2 font-semibold text-neutral-100">
            Хватит
          </button>
        </div>
      </div>
    </div>
  );
}

// ---------- programs ----------
function ProgramsTab({ data, up, exMap, open }) {
  const create = () => {
    const id = uid();
    up((d) => { d.programs.push({ id, name: "Новая программа", items: [] }); });
    open({ type: "program", id });
  };
  return (
    <div className="p-4">
      <Header title="Программы" />
      <div className="space-y-2">
        {data.programs.map((p) => (
          <button key={p.id} onClick={() => open({ type: "program", id: p.id })} className="w-full rounded-xl bg-neutral-900 p-4 text-left active:bg-neutral-800">
            <div className="text-base font-semibold">{p.name}</div>
            <div className="mt-1 text-xs text-neutral-400">{p.items.length} упр., {p.items.reduce((s, i) => s + i.sets, 0)} подх.</div>
          </button>
        ))}
        <button onClick={create} className="w-full rounded-xl border border-dashed border-neutral-700 p-4 text-neutral-300">Новая программа</button>
      </div>
    </div>
  );
}

function ProgramEditor({ data, up, exMap, id, back, goWorkout }) {
  const saved = data.programs.find((x) => x.id === id);
  const [draft, setDraft] = useState(() => (saved ? structuredClone(saved) : null));
  const [picker, setPicker] = useState(false);
  const [leaveAsk, setLeaveAsk] = useState(false);
  const mut = (fn) => setDraft((d) => { const c = structuredClone(d); fn(c); return c; });
  const sort = useSortable((from, to) => mut((pp) => { moveItem(pp.items, from, to); }));
  if (!saved || !draft) return <div className="p-4"><Header title="Программа удалена" back={back} /></div>;

  const p = draft;
  const dirty = JSON.stringify(draft) !== JSON.stringify(saved);
  const save = () => up((d) => { const i = d.programs.findIndex((x) => x.id === id); if (i >= 0) d.programs[i] = structuredClone(draft); });
  const tryBack = () => (dirty ? setLeaveAsk(true) : back());

  return (
    <div className="p-4 pb-44">
      <Header title="Программа" back={tryBack} />
      <input value={p.name} onChange={(e) => mut((pp) => { pp.name = e.target.value; })}
        className="mb-4 w-full rounded-xl bg-neutral-900 px-3 py-3 text-base font-semibold outline-none focus:ring-2 focus:ring-amber-400" />
      <div className="space-y-2">
        {p.items.map((it, i) => (
          <div key={i + it.exerciseId} ref={(el) => { sort.refs.current[i] = el; }} style={sort.itemStyle(i)}
            className={`flex items-center gap-1 rounded-xl p-2 ${sort.dragFrom === i ? "bg-neutral-800" : "bg-neutral-900"}`}>
            <button {...sort.handleProps(i, p.items.length)} className="cursor-grab p-1 text-neutral-500" aria-label="Перетащить">
              <GripVertical size={18} />
            </button>
            <ExImg ex={exMap[it.exerciseId]} size={34} />
            <div className="ml-2 min-w-0 flex-1">
              <div className="truncate">{exMap[it.exerciseId]?.name || "Удалённое упражнение"}</div>
              {exMap[it.exerciseId]?.ru && <div className="truncate text-xs text-neutral-500">{exMap[it.exerciseId].ru}</div>}
            </div>
            <Stepper compact value={it.sets} onChange={(v) => mut((pp) => { pp.items[i].sets = v; })} />
            <button onClick={() => setPicker({ replace: i })} className="p-1 text-neutral-500" aria-label="Заменить"><RefreshCw size={16} /></button>
            <button onClick={() => mut((pp) => { pp.items.splice(i, 1); })} className="p-1 text-neutral-500" aria-label="Убрать"><X size={18} /></button>
          </div>
        ))}
      </div>
      <button onClick={() => setPicker(true)} className="mt-2 w-full rounded-xl border border-dashed border-neutral-700 py-3 text-neutral-300">
        Добавить упражнение
      </button>
      <p className="mt-2 text-xs text-neutral-500">Число справа — сколько подходов подставить при старте.</p>

      <button
        disabled={!!data.active}
        onClick={() => { if (dirty) save(); startWorkout(up, draft); goWorkout(); }}
        className="mt-6 w-full rounded-xl bg-neutral-800 py-3 font-semibold disabled:opacity-40">
        {data.active ? "Уже идёт тренировка" : dirty ? "Сохранить и начать тренировку" : "Начать тренировку"}
      </button>
      <ConfirmButton onConfirm={() => { up((d) => { d.programs = d.programs.filter((x) => x.id !== id); }); back(); }}
        confirmText="Удалить программу?" className="mt-3 w-full py-3 text-neutral-500" armedClassName="mt-3 w-full rounded-xl bg-red-600 py-3 text-white">
        Удалить программу
      </ConfirmButton>

      {(dirty || leaveAsk) && (
        <div className="above-nav fixed inset-x-0 z-40 px-3">
          <div className="mx-auto max-w-md rounded-2xl bg-neutral-900 p-3 shadow-lg">
            {leaveAsk && <p className="mb-2 text-xs text-neutral-300">Есть несохранённые изменения</p>}
            <div className="flex gap-2">
              <button onClick={() => { setDraft(structuredClone(saved)); setLeaveAsk(false); if (leaveAsk) back(); }}
                className="rounded-xl bg-neutral-800 px-4 py-3 text-neutral-300">
                {leaveAsk ? "Не сохранять" : "Отменить"}
              </button>
              <button onClick={() => { save(); if (leaveAsk) back(); setLeaveAsk(false); }}
                className="flex-1 rounded-xl bg-amber-400 py-3 font-semibold text-black">
                Сохранить
              </button>
            </div>
          </div>
        </div>
      )}

      {picker && (
        <Picker data={data} up={up} onClose={() => setPicker(false)}
          title={picker.replace !== undefined ? "Заменить упражнение" : undefined}
          onPick={(ex) => {
            const rep = picker.replace;
            mut((pp) => {
              if (rep !== undefined) { if (pp.items[rep]) pp.items[rep].exerciseId = ex.id; }
              else pp.items.push({ exerciseId: ex.id, sets: 3 });
            });
            setPicker(false);
          }} />
      )}
    </div>
  );
}

// ---------- exercises ----------
function ExerciseDetail({ data, up, exMap, id, back, open }) {
  const [edit, setEdit] = useState(false);
  const ex = exMap[id];
  const sessions = useMemo(() => {
    const out = [];
    for (let i = data.workouts.length - 1; i >= 0; i--) {
      const w = data.workouts[i];
      const e = w.exercises.find((x) => x.exerciseId === id);
      if (e) out.push({ w, sets: e.sets });
    }
    return out;
  }, [data.workouts, id]);
  if (!ex) return <div className="p-4"><Header title="Упражнение удалено" back={back} /></div>;

  const isTime = ex.kind === "time";
  const metric = (sets) => Math.max(...sets.map((s) => (isTime ? num(s.r) : num(s.w))));
  const chart = sessions.slice().reverse().map((s) => ({ date: fmtShort(s.w.startedAt), v: metric(s.sets) }));
  const best = sessions.length ? Math.max(...sessions.map((s) => metric(s.sets))) : 0;
  const mut = (fn) => up((d) => { const e = d.exercises.find((x) => x.id === id); if (e) fn(e); });

  return (
    <div className="p-4 pb-28">
      <Header title={ex.name} back={back}
        right={<button onClick={() => setEdit(!edit)} className="p-2 text-neutral-400" aria-label="Изменить"><Pencil size={20} />
      {ex.ru && <p className="-mt-3 mb-4 text-neutral-400">{ex.ru}</p>}</button>} />

      {edit && (
        <div className="mb-4 rounded-xl bg-neutral-900 p-3">
          <input value={ex.name} placeholder="Название" onChange={(e) => mut((x) => { x.name = e.target.value; })}
            className="mb-2 w-full rounded-lg bg-black px-3 py-2.5 outline-none focus:ring-2 focus:ring-amber-400" />
          <input value={ex.ru || ""} placeholder="Второе название" onChange={(e) => mut((x) => { x.ru = e.target.value; })}
            className="mb-3 w-full rounded-lg bg-black px-3 py-2.5 outline-none focus:ring-2 focus:ring-amber-400" />
          <div className="mb-3 flex flex-wrap gap-1.5">
            {GROUPS.map((g) => (
              <button key={g} onClick={() => mut((x) => { x.group = g; })}
                className={`rounded-full px-3 py-1 text-xs ${ex.group === g ? "bg-amber-400 text-neutral-900" : "bg-neutral-800 text-neutral-300"}`}>{g}</button>
            ))}
          </div>
          <div className="flex gap-1.5">
            {[["reps", "вес и повторы"], ["time", "вес и время"]].map(([k, l]) => (
              <button key={k} onClick={() => mut((x) => { x.kind = k; })}
                className={`rounded-full px-3 py-1 text-xs ${ex.kind === k ? "bg-neutral-100 text-neutral-900" : "bg-neutral-800 text-neutral-300"}`}>{l}</button>
            ))}
          </div>
        </div>
      )}

      <div className="mb-4 flex items-center gap-6">
        <ExImg ex={ex} size={64} />
        <div><div className="text-2xl font-bold tabular-nums">{sessions.length}</div><div className="text-xs text-neutral-400">тренировок</div></div>
        <div><div className="text-2xl font-bold tabular-nums text-amber-400">{best || "—"}</div><div className="text-xs text-neutral-400">{isTime ? "лучшее время, с" : "макс. вес, кг"}</div></div>
      </div>

      {chart.length >= 2 && (
        <div className="mb-4 h-48 rounded-xl bg-neutral-900 p-2">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chart} margin={{ top: 8, right: 8, left: -20, bottom: 0 }}>
              <CartesianGrid stroke="#262626" vertical={false} />
              <XAxis dataKey="date" tick={{ fill: "#a3a3a3", fontSize: 11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: "#a3a3a3", fontSize: 11 }} axisLine={false} tickLine={false} domain={["auto", "auto"]} />
              <Tooltip contentStyle={{ background: "#171717", border: "none", borderRadius: 8 }} labelStyle={{ color: "#a3a3a3" }} />
              <Line type="monotone" dataKey="v" name={isTime ? "сек" : "кг"} stroke="#fbbf24" strokeWidth={2.5} dot={{ r: 3, fill: "#fbbf24" }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {sessions.length === 0 && <p className="text-neutral-400">Истории пока нет. Сделай подход, и он появится здесь.</p>}
      <div className="space-y-2">
        {sessions.map(({ w, sets }) => (
          <button key={w.id} onClick={() => open({ type: "workout", id: w.id })} className="w-full rounded-xl bg-neutral-900 p-3 text-left active:bg-neutral-800">
            <div className="text-xs text-neutral-400">{fmtDate(w.startedAt)}</div>
            <div className="tabular-nums">{fmtSets(sets, ex.kind)}</div>
          </button>
        ))}
      </div>
    </div>
  );
}

// ---------- history ----------
function HistoryTab({ data, exMap, open }) {
  const list = data.workouts.slice().reverse();
  return (
    <div className="p-4">
      <Header title="История" />
      {list.length === 0 && <p className="text-neutral-400">Здесь появятся завершённые тренировки.</p>}
      <div className="space-y-2">
        {list.map((w) => {
          const st = stats(w, exMap);
          return (
            <button key={w.id} onClick={() => open({ type: "workout", id: w.id })} className="w-full rounded-xl bg-neutral-900 p-4 text-left active:bg-neutral-800">
              <div className="text-xs text-neutral-400">{fmtDate(w.startedAt)}</div>
              <div className="font-semibold">{w.name}</div>
              <div className="mt-1 text-xs text-neutral-400 tabular-nums">{fmtWDur(st)}, {fmtKg(st.vol)}, {st.sets} подх.</div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function WorkoutDetail({ data, up, exMap, id, back, open }) {
  const w = data.workouts.find((x) => x.id === id);
  if (!w) return <div className="p-4"><Header title="Тренировка удалена" back={back} /></div>;
  const st = stats(w, exMap);
  return (
    <div className="p-4 pb-28">
      <Header title={w.name} back={back} />
      <p className="-mt-3 mb-4 text-neutral-400">{fmtDate(w.startedAt)}</p>
      <div className="mb-5 grid grid-cols-3 gap-2">
        {[[fmtDur(st.dur), st.extra >= 60000 ? `время, +${fmtDur(st.extra)} позже` : "время"], [fmtKg(st.vol), "объём"], [st.sets, "подходов"]].map(([v, l]) => (
          <div key={l} className="rounded-xl bg-neutral-900 p-3">
            <div className="text-lg font-bold tabular-nums">{v}</div>
            <div className="text-xs text-neutral-400">{l}</div>
          </div>
        ))}
      </div>
      <div className="space-y-2">
        {w.exercises.map((e, i) => {
          const ex = exMap[e.exerciseId] || { name: "Удалённое упражнение", kind: "reps" };
          return (
            <button key={i} onClick={() => open({ type: "exercise", id: e.exerciseId })} className="flex w-full items-center gap-3 rounded-xl bg-neutral-900 p-3 text-left active:bg-neutral-800">
              <ExImg ex={exMap[e.exerciseId]} />
              <div className="min-w-0 flex-1">
                <div className="font-semibold">{ex.name}</div>
                <div className="text-xs text-neutral-300 tabular-nums">{fmtSets(e.sets, ex.kind)}</div>
              </div>
            </button>
          );
        })}
      </div>
      <ConfirmButton onConfirm={() => { up((d) => { d.workouts = d.workouts.filter((x) => x.id !== id); }); back(); }}
        confirmText="Удалить из истории?" className="mt-6 w-full py-3 text-neutral-500" armedClassName="mt-6 w-full rounded-xl bg-red-600 py-3 text-white">
        Удалить тренировку
      </ConfirmButton>
    </div>
  );
}

// ---------- settings ----------
function SettingsTab({ data, up, replace, saved }) {
  const [exp, setExp] = useState("");
  const [imp, setImp] = useState("");
  const [msg, setMsg] = useState("");
  const doExport = async () => {
    const txt = JSON.stringify({ ...data, exportedAt: new Date().toISOString() });
    setExp(txt);
    try { await navigator.clipboard.writeText(txt); setMsg("Скопировано в буфер обмена"); }
    catch (e) { setMsg("Скопируй текст из поля вручную"); }
  };
  const doImport = () => {
    try {
      const d = JSON.parse(imp);
      if (!Array.isArray(d.exercises) || !Array.isArray(d.programs) || !Array.isArray(d.workouts)) throw new Error();
      replace(migrate({ settings: { restSec: 120 }, active: null, ...d }));
      setImp(""); setMsg("Данные загружены");
    } catch (e) { setMsg("Это не похоже на экспорт из приложения"); }
  };
  return (
    <div className="p-4 pb-28">
      <Header title="Настройки" />
      <p className={`-mt-2 mb-4 text-xs ${saved.state === "error" ? "text-red-400" : "text-neutral-500"}`}>
        {saved.state === "error" ? `Не сохраняется: ${saved.msg}`
          : saved.at ? `Сохранено в ${new Date(saved.at).toLocaleTimeString("ru-RU")}` : "Изменений пока не было"}
      </p>
      <div className="mb-6 flex items-center justify-between rounded-xl bg-neutral-900 p-4">
        <div><div className="font-semibold">Отдых между подходами</div><div className="text-xs text-neutral-400">Для всех упражнений</div></div>
        <Stepper value={data.settings.restSec} step={15} min={15} fmt={(v) => fmtDur(v * 1000)}
          onChange={(v) => up((d) => { d.settings.restSec = v; })} />
      </div>

      <h2 className="mb-2 font-semibold">Резервная копия</h2>
      <button onClick={doExport} className="w-full rounded-xl bg-neutral-900 py-3 active:bg-neutral-800">Скопировать все данные</button>
      {exp && <textarea readOnly value={exp} onFocus={(e) => e.target.select()} className="mt-2 h-24 w-full rounded-xl bg-neutral-900 p-3 text-xs text-neutral-400" />}

      <textarea value={imp} onChange={(e) => setImp(e.target.value)} placeholder="Вставь сюда сохранённую копию"
        className="mt-4 h-24 w-full rounded-xl bg-neutral-900 p-3 text-xs outline-none placeholder-neutral-500 focus:ring-2 focus:ring-amber-400" />
      {imp && (
        <ConfirmButton onConfirm={doImport} confirmText="Заменить всё текущее?"
          className="mt-2 w-full rounded-xl bg-neutral-800 py-3" armedClassName="mt-2 w-full rounded-xl bg-red-600 py-3 text-white">
          Загрузить копию
        </ConfirmButton>
      )}
      {msg && <p className="mt-3 text-xs text-amber-400">{msg}</p>}
      <p className="mt-8 text-xs text-neutral-600">
        Версия от {new Date(__BUILD_TIME__).toLocaleString("ru-RU", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}
      </p>
    </div>
  );
}

// ---------- app ----------
const TABS = [
  ["workout", "Тренировка", Dumbbell],
  ["history", "История", History],
  ["programs", "Программы", ListChecks],
  ["exercises", "Упражнения", Library],
  ["settings", "Настройки", Settings],
];

export default function App() {
  const [data, setData] = useState(null);
  const [err, setErr] = useState("");
  const [tab, setTab] = useState("workout");
  const [stack, setStack] = useState([]);
  const dataRef = useRef(null);
  dataRef.current = data;

  const [saved, setSaved] = useState({ state: "idle", at: 0, msg: "" });
  const [loadKey, setLoadKey] = useState(0);

  // Load. get() throws both for a missing key and for a real failure, so when it throws
  // we probe the storage: if a test write/read works, the key is simply missing.
  useEffect(() => {
    (async () => {
      setErr("");
      const errs = [];
      for (const k of [KEY, KEY + "-backup"]) {
        try {
          const r = await storage.get(k, false);
          if (r && r.value) { setData(migrate(JSON.parse(r.value))); return; }
        } catch (e) { errs.push(`${k}: ${e && e.message ? e.message : e}`); }
      }
      try {
        const v = String(Date.now());
        await storage.set("gymapp-probe", v, false);
        const p = await storage.get("gymapp-probe", false);
        if (p && p.value === v) { setData(seed()); return; }
        errs.push("проверочная запись не прочиталась");
      } catch (e) { errs.push(`проверка: ${e && e.message ? e.message : e}`); }
      setErr("Хранилище не отвечает, данные не тронуты.\n" + errs.join("\n"));
    })();
  }, [loadKey]);

  const persist = async (d) => {
    if (!d) return;
    setSaved((x) => ({ ...x, state: "saving" }));
    try {
      const r = await storage.set(KEY, JSON.stringify(d), false);
      if (!r) throw new Error("хранилище не подтвердило запись");
      setSaved({ state: "ok", at: Date.now(), msg: "" });
    } catch (e) {
      setSaved({ state: "error", at: 0, msg: String(e && e.message ? e.message : e) });
    }
  };

  const saveT = useRef(null);
  useEffect(() => {
    if (!data) return;
    clearTimeout(saveT.current);
    saveT.current = setTimeout(() => persist(data), 150);
  }, [data]);

  // flush pending changes when the app is hidden or closed
  useEffect(() => {
    const flush = () => {
      clearTimeout(saveT.current);
      const d = dataRef.current;
      if (!d) return;
      persist(d);
      try { storage.set(KEY + "-backup", JSON.stringify(d), false); } catch (e) {}
    };
    const onVis = () => { if (document.visibilityState === "hidden") flush(); };
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("pagehide", flush);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pagehide", flush);
      flush();
    };
  }, []);

  const autoClosed = useRef(false);
  useEffect(() => {
    if (!data || autoClosed.current) return;
    autoClosed.current = true;
    const a = data.active;
    if (!a || !a.paused) return;
    const segs = segmentsOf(a);
    const lastEnd = segs[segs.length - 1].end || a.startedAt;
    if (new Date(lastEnd).toDateString() === new Date().toDateString()) return;
    setData((d0) => {
      const d = structuredClone(d0);
      const w = d.active;
      const p = w.programId && d.programs.find((x) => x.id === w.programId);
      const items = w.exercises.map((e) => ({ exerciseId: e.exerciseId, sets: e.sets.length || 1 }));
      if (p && JSON.stringify(p.items) !== JSON.stringify(items)) d.pendingProgramUpdate = { programId: p.id, items };
      finalizeActive(d, false);
      return d;
    });
  }, [data]);

  const up = (fn) => setData((d) => { const c = structuredClone(d); fn(c); return c; });
  const exMap = useMemo(() => (data ? Object.fromEntries(data.exercises.map((e) => [e.id, e])) : {}), [data?.exercises]);
  const open = (v) => setStack((s) => [...s, v]);
  const back = () => setStack((s) => s.slice(0, -1));

  if (err) return (
    <div className="min-h-screen bg-black p-6 text-neutral-100">
      <p className="mb-4 whitespace-pre-wrap text-xs text-neutral-400">{err}</p>
      <button onClick={() => setLoadKey((k) => k + 1)} className="w-full rounded-xl bg-amber-400 py-3 font-semibold text-black">Попробовать ещё раз</button>
      <ConfirmButton onConfirm={() => { setErr(""); setData(seed()); }} confirmText="Старые данные будут перезаписаны"
        className="mt-3 w-full py-3 text-neutral-500" armedClassName="mt-3 w-full rounded-xl bg-red-600 py-3 text-white">
        Начать с чистого листа
      </ConfirmButton>
    </div>
  );
  if (!data) return <div className="flex min-h-screen items-center justify-center bg-black text-neutral-400">Загружаю…</div>;

  const view = stack[stack.length - 1];
  const common = { data, up, exMap, open, back };
  let content;
  if (view?.type === "exercise") content = <ExerciseDetail {...common} id={view.id} />;
  else if (view?.type === "workout") content = <WorkoutDetail {...common} id={view.id} />;
  else if (view?.type === "program") content = <ProgramEditor {...common} id={view.id} goWorkout={() => { setStack([]); setTab("workout"); }} />;
  else if (tab === "workout") content = <WorkoutTab {...common} />;
  else if (tab === "history") content = <HistoryTab {...common} />;
  else if (tab === "programs") content = <ProgramsTab {...common} />;
  else if (tab === "exercises") content = (
    <div className="p-4 pb-28"><Header title="Упражнения" /><ExerciseList data={data} up={up} onSelect={(e) => open({ type: "exercise", id: e.id })} /></div>
  );
  else content = <SettingsTab data={data} up={up} saved={saved} replace={(d) => { setData(d); setStack([]); }} />;

  return (
    <div className="min-h-screen bg-black text-sm text-neutral-100">
      {saved.state === "error" && (
        <div className="fixed inset-x-0 top-0 z-50 bg-red-600 px-4 py-2 text-center text-xs text-white">
          Изменения не сохраняются. Сделай копию в настройках.
        </div>
      )}
      <div className="mx-auto max-w-md pb-20">{content}</div>

      {data.active?.restEndsAt && <RestBar key={data.active.restEndsAt} endsAt={data.active.restEndsAt} total={data.settings.restSec} up={up} />}

      <nav className="safe-bottom fixed inset-x-0 bottom-0 z-40 border-t border-neutral-800 bg-black">
        <div className="mx-auto flex max-w-md">
          {TABS.map(([k, l, I]) => (
            <button key={k} onClick={() => { setTab(k); setStack([]); }}
              className={`relative flex flex-1 flex-col items-center gap-0.5 py-2.5 text-xs ${tab === k && !view ? "text-amber-400" : "text-neutral-500"}`}>
              <I size={20} />
              {l}
              {k === "workout" && data.active && <span className="absolute right-1/4 top-1.5 h-2 w-2 rounded-full bg-amber-400" />}
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
}
